settings.custom_liquid:
{%- assign v = product.selected_or_first_available_variant -%}
{%- if v.compare_at_price > v.price -%}<p class="sn-pdp-save">Du sparst <b>{{ v.compare_at_price | minus: v.price | money_without_currency | append: ' €' }}</b> ({{ v.compare_at_price | minus: v.price | times: 100 | divided_by: v.compare_at_price }} %)</p>{%- endif -%}
{%- assign sn_left = 4400 | minus: cart.total_price | minus: v.price -%}
<p class="sn-pdp-ship">{% render 'schnappy-icon', icon: 'truck' %}{%- if sn_left > 0 -%}<span>Noch <b>{{ sn_left | money_without_currency | append: ' €' }}</b> bis zum <b>Gratis-Versand</b></span>{%- else -%}<span>Mit diesem Artikel: <b>Gratis-Versand</b></span>{%- endif -%}</p>
{%- if v.available -%}<p class="sn-instock sn-instock--lg"><i aria-hidden="true"></i>Sofort lieferbar</p>{%- endif -%}
<p class="sn-pdp-tax">inkl. MwSt., zzgl. <a href="{% render 'schnappy-page-url', handle: 'versand' %}">Versand</a></p>
{%- if v.price >= 3000 -%}<p class="sn-pdp-klarna"><span>Klarna.</span> Bezahle später oder in 3 Raten.</p>{%- endif -%}
{%- for t in product.tags -%}{%- assign tl = t | downcase -%}{%- if tl contains 'alter-' -%}{%- assign age = tl | remove: 'alter-' | remove: 'jahre' | remove: '-' -%}<p class="sn-pdp-age">{% render 'schnappy-icon', icon: 'baby' %} Empfohlen ab {{ age }} Jahren</p>{%- break -%}{%- endif -%}{%- endfor -%}

{%- assign t = product.title | split: ' //' | first | strip -%}
<div class="sn-pdp-actions">
  <button type="button" class="sn-pdp-act" data-sn-heart="{{ product.handle }}" aria-pressed="false">{% render 'schnappy-icon', icon: 'heart' %}<span>Merken</span></button>
  <a class="sn-pdp-act sn-pdp-act--wa" href="https://wa.me/?text={{ t | append: ' – ' | append: shop.url | append: product.url | url_encode }}" target="_blank" rel="noopener">{% render 'schnappy-icon', icon: 'message-circle' %}<span>Per WhatsApp teilen</span></a>
  <a class="sn-pdp-act" href="https://ig.me/m/schnappy.shop" target="_blank" rel="noopener" data-sn-copy="{{ shop.url }}{{ product.url }}">{% render 'schnappy-icon', icon: 'instagram' %}<span>Frage auf Instagram</span></a>
</div>
{%- unless product.available -%}
  <div class="sn-notify">
    <h3>Wieder da? Wir sagen dir Bescheid.</h3>
    {%- form 'contact', class: 'sn-notify__form' -%}
      {%- if form.posted_successfully? -%}<p class="sn-notify__ok">✓ Danke! Wir melden uns, sobald der Artikel wieder da ist.</p>{%- else -%}
      <input type="hidden" name="contact[Betreff]" value="Benachrichtigung: {{ t | escape }}">
      <input type="hidden" name="contact[body]" value="Bitte benachrichtigen, wenn wieder verfügbar: {{ t | escape }} ({{ shop.url }}{{ product.url }})">
      <label class="visually-hidden" for="SnNotify">E-Mail</label>
      <input id="SnNotify" type="email" name="contact[email]" required placeholder="Deine E-Mail" autocomplete="email">
      <button type="submit">Benachrichtigen</button>
      {%- endif -%}
    {%- endform -%}
  </div>
{%- endunless -%}
